/** Parse action files once at the file-loading boundary. */
export function parseActionDefinitionFiles(files) {
    return files.map((file) => parseActionFile(file))
}

/** Validate and resolve a whole-project graph of structured action definitions. */
export function validateActionDefinitionGraph(entries, dependencies = {}) {
    const rawDefinitions = entries.map(({ definition, path }) => validateRawDefinition(definition, path, dependencies))
    const ids = new Set(BUILTIN_ACTIONS.map(({ id }) => id))
    const normalizedIds = new Map(BUILTIN_ACTIONS.map(({ id }) => [normalizeActionId(id), id]))
    for (const raw of rawDefinitions) {
        if (ids.has(raw.id)) throw fail(`Duplicate action id ${raw.id} in ${raw.sourcePath}`, 'duplicate-id', raw.sourcePath, 'id')
        const normalizedId = normalizeActionId(raw.id)
        const collidingId = normalizedIds.get(normalizedId)
        if (collidingId) {
            throw fail(
                `Action id ${raw.id} in ${raw.sourcePath} collides with ${collidingId} after normalization`,
                'normalized-id-collision',
                raw.sourcePath,
                'id',
            )
        }
        ids.add(raw.id)
        normalizedIds.set(normalizedId, raw.id)
    }

    const registry = new Map(BUILTIN_ACTIONS.map((action) => [action.id, action]))
    for (const raw of rawDefinitions) {
        registry.set(raw.id, {
            agent: raw.agent ?? null,
            appliesTo: raw.appliesTo ?? null,
            autoFinish: raw.autoFinish ?? null,
            builtin: false,
            command: raw.command ?? null,
            description: raw.description,
            icon: raw.icon ?? null,
            id: raw.id,
            label: raw.label,
            model: raw.model ?? null,
            needsWorkTree: raw.needsWorkTree,
            on: [],
            onAfter: [],
            onBefore: [],
            onState: raw.onState ?? null,
            output: raw.output ?? null,
            phrases: raw.phrases,
            permissionMode: raw.permissionMode ?? null,
            prompt: raw.prompt ?? null,
            showCommandWindow: raw.showCommandWindow,
            sourcePath: raw.sourcePath,
            thinkingLevel: raw.thinkingLevel ?? null,
            ...(raw.speedMode !== undefined ? { speedMode: raw.speedMode } : {}),
            trackFileChanges: raw.trackFileChanges,
            streaming: raw.streaming,
            type: raw.type,
            userInput: raw.userInput ?? null,
        })
    }

    for (const raw of rawDefinitions) {
        const action = registry.get(raw.id)
        action.onBefore = raw.onBefore.map((actionId, index) => resolveAction(actionId, registry, raw.sourcePath, 'onBefore', index))
        action.onAfter = raw.onAfter.map((actionId, index) => resolveAction(actionId, registry, raw.sourcePath, 'onAfter', index))
        action.on = raw.on.map(({ actionId, condition }, index) => ({
            action: resolveAction(actionId, registry, raw.sourcePath, 'on', index),
            actionId,
            condition,
        }))
    }

    const actions = [...BUILTIN_ACTIONS, ...rawDefinitions.map(({ id }) => registry.get(id))]
    detectCycles(actions)

    return actions
}

export function loadActionDefinitions(files, dependencies = {}) {
    return validateActionDefinitionGraph(parseActionDefinitionFiles(files), dependencies)
}

import { normalizePath } from './path_utils.mjs';

export const ACCOUNT_AGENTS = ['codex', 'claude'];
export const INITIAL_ACCOUNT_KIND = 'initial';
export const DIRECTORY_ACCOUNT_KIND = 'directory';
const INITIAL_ACCOUNT_NAME = 'Default';
const INITIAL_ACCOUNT_ID_SUFFIX = '-initial';
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu;
const WINDOWS_ABSOLUTE_PATH_PATTERN = /^(?:[A-Za-z]:\/|\/\/[^/])/u;
const TRAILING_SEPARATOR_PATTERN = /\/+$/u;

/** Reserved ID of the account that uses the CLI login of the inherited environment. */
export function initialAgentAccountId(agent) {
    return `${agent}${INITIAL_ACCOUNT_ID_SUFFIX}`;
}

export function supportsAgentAccounts(agent) {
    return ACCOUNT_AGENTS.includes(agent);
}

export const DEFAULT_AGENT_ACCOUNTS = ACCOUNT_AGENTS.map((agent) => (
    { id: initialAgentAccountId(agent), agent, kind: INITIAL_ACCOUNT_KIND, name: INITIAL_ACCOUNT_NAME }
));

function requireAccountString(value, fieldName) {
    if (typeof value !== 'string' || value.trim().length === 0) throw new Error(`Invalid agent account field: ${fieldName}`);

    return value;
}

function isWindowsPath(directory) {
    return WINDOWS_ABSOLUTE_PATH_PATTERN.test(directory);
}

function normalizeConfigDirectory(value, fieldName) {
    const directory = normalizePath(requireAccountString(value, fieldName));
    const isAbsolute = isWindowsPath(directory) || directory.startsWith('/');
    if (!isAbsolute) throw new Error(`Agent account directory must be absolute: ${fieldName}`);
    const trimmed = directory.replace(TRAILING_SEPARATOR_PATTERN, '');

    return trimmed.length === 0 || trimmed.endsWith(':') ? `${trimmed}/` : trimmed;
}

/** Comparison key for directory uniqueness: Windows paths are case-insensitive, POSIX paths are not. */
function directoryComparisonKey(directory) {
    return isWindowsPath(directory) ? directory.toLowerCase() : directory;
}

function validateAgentAccount(value, source) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Invalid agent account: ${source}`);
    const id = requireAccountString(value.id, `${source}.id`);
    const agent = requireAccountString(value.agent, `${source}.agent`);
    if (!supportsAgentAccounts(agent)) throw new Error(`Agent does not support accounts in ${source}: ${agent}`);
    const name = requireAccountString(value.name, `${source}.name`);
    if (value.kind === INITIAL_ACCOUNT_KIND) {
        if (id !== initialAgentAccountId(agent)) throw new Error(`Invalid initial agent account ID in ${source}: ${id}`);
        if (value.configDirectory !== undefined) throw new Error(`Initial agent account cannot have a directory: ${source}`);

        return { id, agent, kind: INITIAL_ACCOUNT_KIND, name };
    }
    if (value.kind !== DIRECTORY_ACCOUNT_KIND) throw new Error(`Invalid agent account kind in ${source}: ${String(value.kind)}`);
    if (!UUID_PATTERN.test(id)) throw new Error(`Agent account ID must be a UUID in ${source}: ${id}`);
    const configDirectory = normalizeConfigDirectory(value.configDirectory, `${source}.configDirectory`);

    return { id, agent, kind: DIRECTORY_ACCOUNT_KIND, name, configDirectory };
}

function requireUniqueValues(keys, label, source) {
    const seen = new Set();
    for (const key of keys) {
        if (seen.has(key)) throw new Error(`Duplicate agent account ${label} in ${source}: ${key}`);
        seen.add(key);
    }
}

/** Validates the full account collection, including uniqueness and one initial account per supported agent. */
export function validateAgentAccounts(value, source) {
    if (!Array.isArray(value)) throw new Error(`Invalid agent accounts in ${source}`);
    const accounts = value.map((account, index) => validateAgentAccount(account, `${source}[${index}]`));
    requireUniqueValues(accounts.map(({ id }) => id), 'ID', source);
    requireUniqueValues(accounts.map(({ agent, name }) => `${agent}/${name}`), 'name', source);
    const directories = accounts.filter(({ kind }) => kind === DIRECTORY_ACCOUNT_KIND)
        .map(({ configDirectory }) => directoryComparisonKey(configDirectory));
    requireUniqueValues(directories, 'directory', source);
    for (const agent of ACCOUNT_AGENTS) {
        const hasInitial = accounts.some((account) => account.agent === agent && account.kind === INITIAL_ACCOUNT_KIND);
        if (!hasInitial) throw new Error(`Missing initial agent account for ${agent} in ${source}`);
    }

    return accounts;
}

/** A missing collection resolves to the initial accounts without persisting them. */
export function resolveAgentAccounts(value, source) {
    if (value === undefined) return structuredClone(DEFAULT_AGENT_ACCOUNTS);

    return validateAgentAccounts(value, source);
}

export function findAgentAccount(accounts, accountId) {
    return accounts.find(({ id }) => id === accountId) ?? null;
}

/**
 * Resolves the account for an agent. A missing account ID resolves to the initial account;
 * an explicit invalid account ID is an error and never falls back to the initial account.
 */
export function resolveAgentAccount(accounts, agent, accountId) {
    if (!supportsAgentAccounts(agent)) {
        if (accountId !== undefined) throw new Error(`Agent profile does not support accounts: ${agent}`);

        return null;
    }
    const targetId = accountId ?? initialAgentAccountId(agent);
    const account = findAgentAccount(accounts, targetId);
    if (!account) throw new Error(`Unknown agent account for ${agent}: ${targetId}`);
    if (account.agent !== agent) throw new Error(`Agent account ${targetId} belongs to ${account.agent}, not ${agent}`);

    return account;
}

import {
    DEFAULT_AGENT_PROFILE_NAME,
    DEFAULT_PERMISSION_MODE,
    defaultModelForProfile,
    defaultThinkingLevelForProfile,
    findAgentProfile,
    supportsPermissionMode,
    validatePermissionMode,
    validateThinkingLevel,
    validateSpeedMode,
} from './agent_profiles.mjs'
import { resolveAgentAccount } from './agent_accounts.mjs'

const defaultProfile = findAgentProfile([], DEFAULT_AGENT_PROFILE_NAME)
if (!defaultProfile) throw new Error(`Missing built-in agent profile: ${DEFAULT_AGENT_PROFILE_NAME}`)

export const DEFAULT_AGENT_SELECTION = {
    activeAgent: DEFAULT_AGENT_PROFILE_NAME,
    permissionMode: DEFAULT_PERMISSION_MODE,
    settingsByAgent: { [DEFAULT_AGENT_PROFILE_NAME]: profileAgentSettings(defaultProfile) },
}

function requireObject(value, source) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Invalid agent selection in ${source}`)

    return value
}

function requireString(value, fieldName, allowEmpty = false) {
    if (typeof value !== 'string' || (!allowEmpty && value.length === 0)) throw new Error(`Invalid agent selection field: ${fieldName}`)

    return value
}

export function profileAgentSettings(profile) {
    return {
        model: defaultModelForProfile(profile),
        thinkingLevel: defaultThinkingLevelForProfile(profile),
    }
}

export function validateAgentSettings(value, source) {
    const settings = requireObject(value, source)

    return {
        model: requireString(settings.model, `${source}.model`, true),
        thinkingLevel: validateThinkingLevel(settings.thinkingLevel, `${source}.thinkingLevel`),
        ...(settings.speedMode !== undefined ? { speedMode: validateSpeedMode(settings.speedMode, `${source}.speedMode`) } : {}),
        ...(settings.accountId !== undefined ? { accountId: requireString(settings.accountId, `${source}.accountId`) } : {}),
    }
}

export function validateAgentSelectionState(value, source, allowEmptyPermissionMode = false) {
    const selection = requireObject(value, source)
    const activeAgent = requireString(selection.activeAgent, `${source}.activeAgent`)
    const permissionMode = requireString(selection.permissionMode, `${source}.permissionMode`, allowEmptyPermissionMode)
    if (permissionMode.length > 0) validatePermissionMode(permissionMode, `${source}.permissionMode`)
    const rawSettingsByAgent = requireObject(selection.settingsByAgent, `${source}.settingsByAgent`)
    const settingsByAgent = Object.fromEntries(Object.entries(rawSettingsByAgent).map(([agent, settings]) => [
        requireString(agent, `${source}.settingsByAgent agent`),
        validateAgentSettings(settings, `${source}.settingsByAgent.${agent}`),
    ]))

    return { activeAgent, permissionMode, settingsByAgent }
}

export function resolveAgentSettings(agent, profiles, sources = []) {
    const remembered = sources.find((source) => source?.settingsByAgent && Object.hasOwn(source.settingsByAgent, agent))
    if (remembered) {
        const speedMode = sources.find((source) => source?.settingsByAgent?.[agent]?.speedMode !== undefined)
            ?.settingsByAgent[agent].speedMode;

        return speedMode === undefined ? remembered.settingsByAgent[agent] : { ...remembered.settingsByAgent[agent], speedMode };
    }

    const profile = findAgentProfile(profiles, agent)
    if (!profile) return { model: '', thinkingLevel: 'none' }

    return profileAgentSettings(profile)
}

export function resolveAgentSelectionState(selection, profiles, fallbackSources = []) {
    const currentSettings = selection.settingsByAgent[selection.activeAgent];
    const activeSettings = resolveAgentSettings(selection.activeAgent, profiles, [selection, ...fallbackSources]);
    if (currentSettings && currentSettings.speedMode === activeSettings.speedMode) return selection;

    return {
        ...selection,
        settingsByAgent: { ...selection.settingsByAgent, [selection.activeAgent]: activeSettings },
    }
}

export function selectSpeedMode(selection, speedMode) {
    const current = selection.settingsByAgent[selection.activeAgent];
    if (!current) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`);
    const validated = validateSpeedMode(speedMode, 'agent selection');
    if (selection.activeAgent !== 'codex' && validated !== 'default') {
        throw new Error(`Speed settings are unsupported for ${selection.activeAgent}`);
    }

    return {
        ...selection,
        settingsByAgent: { ...selection.settingsByAgent, [selection.activeAgent]: { ...current, speedMode: validated } },
    };
}

/** Remembers the account for the active agent; an invalid explicit account is rejected, never replaced. */
export function selectAccount(selection, accountId, accounts) {
    const current = selection.settingsByAgent[selection.activeAgent];
    if (!current) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`);
    resolveAgentAccount(accounts, selection.activeAgent, accountId);

    return {
        ...selection,
        settingsByAgent: { ...selection.settingsByAgent, [selection.activeAgent]: { ...current, accountId } },
    };
}

export function selectAgent(selection, agent, profiles, fallbackSources = []) {
    const next = { ...selection, activeAgent: agent }

    return resolveAgentSelectionState(next, profiles, fallbackSources)
}

export function selectModel(selection, model) {
    const current = selection.settingsByAgent[selection.activeAgent]
    if (!current) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`)

    return {
        ...selection,
        settingsByAgent: { ...selection.settingsByAgent, [selection.activeAgent]: { ...current, model } },
    }
}

export function selectThinkingLevel(selection, thinkingLevel) {
    const current = selection.settingsByAgent[selection.activeAgent]
    if (!current) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`)
    const validated = validateThinkingLevel(thinkingLevel, `agent selection ${selection.activeAgent}`)

    return {
        ...selection,
        settingsByAgent: {
            ...selection.settingsByAgent,
            [selection.activeAgent]: { ...current, thinkingLevel: validated },
        },
    }
}

export function selectPermissionMode(selection, permissionMode) {
    return { ...selection, permissionMode: validatePermissionMode(permissionMode, 'agent selection') }
}

export function projectAgentSelection(selection, profiles = []) {
    const settings = selection.settingsByAgent[selection.activeAgent]
    if (!settings) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`)
    const profile = findAgentProfile(profiles, selection.activeAgent)

    return {
        agent: selection.activeAgent,
        model: settings.model,
        ...(profile && supportsPermissionMode(profile) ? { permissionMode: selection.permissionMode } : {}),
        thinkingLevel: settings.thinkingLevel,
        ...(settings.speedMode !== undefined ? { speedMode: settings.speedMode } : {}),
        ...(settings.accountId !== undefined ? { accountId: settings.accountId } : {}),
    }
}

