export type ScheduleTrigger = NowScheduleTrigger | AtScheduleTrigger | AccountResetScheduleTrigger | CardStateScheduleTrigger
export type ActionScheduleTrigger = Exclude<ScheduleTrigger, NowScheduleTrigger>

interface ScheduleBase {
    createdAt: string
    id: string
    status: ScheduleStatus
    trigger: ScheduleTrigger
}

export interface ActionSchedule extends ScheduleBase {
    actionId: string
    context: ActionContext
    conversationId?: string | null
    failure?: string | null
    kind: 'action'
    prompt?: string
    trigger: ActionScheduleTrigger
}

export interface SequenceSchedule extends ScheduleBase {
    agentSelection?: AgentSelection
    worktreeBranch?: string;
    branchProgress?: SequenceBranchProgress;
    actionCompleted: boolean
    actionId: string
    cardInternalIds: string[]
    conversationId?: string | null
    currentIndex: number
    currentRunId: string | null
    failure: string | null
    kind: 'sequence'
    readyState: string
    runId: string,
    requestId: AgentApprovalRequestId,
    decision: AgentApprovalDecision,
) {
    return answerActionApproval(runId, requestId, decision)
}

export async function defaultScheduleAction(
    action: ActionDefinition,
    context: ActionContext,
    trigger: ActionScheduleTrigger,
    prompt: string,
    conversationId?: string,
) {
    projectAccessService.requireWritable()
    const bridge = getElectronActionBridge()
    if (!bridge?.registerActionSchedule) throw new Error('Scheduling actions requires Electron local mode')
    if (action.id === CUSTOM_PROMPT_ACTION_ID && prompt.trim().length === 0) {
        throw new Error('Custom prompt cannot be empty')
    }

    const request = {
        actionId: action.id,
        ...(action.type === 'agent' && conversationId ? { conversationId } : {}),
        context,
        ...(action.type === 'agent' ? { prompt } : {}),
        trigger,
    }
    await bridge.registerActionSchedule(request)
    await activeScheduleService.refresh()
    const { error } = activeScheduleService.getSnapshot()
    if (error) throw new Error(error)
}

